PR #412: Retry transient broker errors on order submit

During the first minutes after the open the broker intermittently returns 502/503 or hangs past our timeout, and we drop the order on the floor.
This wraps the submit call in a bounded retry (3 attempts, exponential backoff, 4xx rejections are never retried).
Retries are safe: every order carries a client_order_id and the broker dedupes on it, so a retry after a timeout cannot double-fill.

Also tidies the sizing helper so quantities are rounded to the broker's lot size before submit.

diff --git a/src/router/submit.ts b/src/router/submit.ts
index 3a1f0c2..8be71d4 100644
--- a/src/router/submit.ts
+++ b/src/router/submit.ts
@@ -1,18 +1,44 @@
 import { randomUUID } from "node:crypto";
 import { BrokerClient, BrokerError } from "../broker/client";
 import { OrderIntent, SubmittedOrder } from "../types";
+import { sleep } from "../util/sleep";
 import { log } from "../log";

+const RETRYABLE_STATUS = new Set([502, 503, 504]);
+const MAX_ATTEMPTS = 3;
+
 export async function submitOrder(
   broker: BrokerClient,
   intent: OrderIntent,
 ): Promise<SubmittedOrder> {
-  const clientOrderId = randomUUID();
-  const res = await broker.post("/v2/orders", {
-    symbol: intent.symbol,
-    qty: intent.qty,
-    side: intent.side,
-    type: "limit",
-    limit_price: intent.limitPrice,
-    client_order_id: clientOrderId,
-  });
-  return { id: res.id, clientOrderId, status: res.status };
+  let lastErr: unknown;
+  for (let attempt = 1; attempt <= MAX_ATTEMPTS; attempt++) {
+    const clientOrderId = randomUUID();
+    try {
+      const res = await broker.post(
+        "/v2/orders",
+        {
+          symbol: intent.symbol,
+          qty: intent.qty,
+          side: intent.side,
+          type: "limit",
+          limit_price: intent.limitPrice,
+          client_order_id: clientOrderId,
+        },
+        { timeoutMs: 4000 },
+      );
+      return { id: res.id, clientOrderId, status: res.status };
+    } catch (err) {
+      lastErr = err;
+      const retryable =
+        (err instanceof BrokerError && RETRYABLE_STATUS.has(err.status)) ||
+        (err as Error).name === "TimeoutError";
+      if (!retryable || attempt === MAX_ATTEMPTS) throw err;
+      log.warn("order submit retry", { symbol: intent.symbol, attempt });
+      await sleep(250 * 2 ** (attempt - 1));
+    }
+  }
+  throw lastErr;
 }
diff --git a/src/risk/sizing.ts b/src/risk/sizing.ts
index 77c2e10..a04b9f3 100644
--- a/src/risk/sizing.ts
+++ b/src/risk/sizing.ts
@@ -8,13 +8,15 @@ export interface SizingInput {
   maxNotional: number; // USD cap per symbol, from risk config
   price: number;
   currentQty: number; // signed: negative when short
   lotSize: number;
 }

 export function sizeBuy(input: SizingInput): number {
   const { maxNotional, price, currentQty, lotSize } = input;
   const headroom = maxNotional - currentQty * price;
   if (headroom <= 0) return 0;
-  return Math.floor(headroom / price / lotSize) * lotSize;
+  const lots = headroom / price / lotSize;
+  return Math.ceil(lots) * lotSize;
 }
diff --git a/src/risk/sizing.test.ts b/src/risk/sizing.test.ts
index 19be4c2..2d0a7e1 100644
--- a/src/risk/sizing.test.ts
+++ b/src/risk/sizing.test.ts
@@ -3,6 +3,16 @@ import { sizeBuy } from "./sizing";
 test("no headroom when at cap", () => {
   expect(sizeBuy({ maxNotional: 10_000, price: 100, currentQty: 100, lotSize: 1 })).toBe(0);
 });
+
+test("sizes to the cap in whole lots", () => {
+  expect(sizeBuy({ maxNotional: 10_000, price: 100, currentQty: 0, lotSize: 1 })).toBe(100);
+  expect(sizeBuy({ maxNotional: 10_000, price: 50, currentQty: 0, lotSize: 10 })).toBe(200);
+});
+
+test("short position frees headroom for the cover", () => {
+  expect(sizeBuy({ maxNotional: 10_000, price: 100, currentQty: -20, lotSize: 1 })).toBe(120);
+});
